package com.hbm.satellite.cargo;
import com.hbm.entity.projectile.EntityThrowableInterp;import com.hbm.entity.LegacyTrackingRange;import api.hbm.entity.IRadarDetectableNT;import net.minecraft.nbt.*;import net.minecraft.network.syncher.*;import net.minecraft.world.entity.*;import net.minecraft.world.damagesource.DamageSource;import net.minecraft.world.item.ItemStack;import net.minecraft.world.level.Level;import net.minecraft.world.phys.*;
/** Actual EntitySatellitePod/EntityThrowableInterp: cargo, landing+braking,100tickunload and departure. */
public final class SatellitePod extends EntityThrowableInterp implements IRadarDetectableNT,LegacyTrackingRange {
 private static final EntityDataAccessor<Integer> STATE=SynchedEntityData.defineId(SatellitePod.class,EntityDataSerializers.INT);public static final int STATE_LEGS_UP=0,STATE_LEGS_DOWN=1;public ItemStack[] slots=new ItemStack[0];public int timer,callerYPos;public double speed=.75D;public float legs,prevLegs;public static final float LEG_SPEED=1F/20F;
 public SatellitePod(EntityType<? extends SatellitePod> type,Level level){super(type,level);noCulling=true;}public SatellitePod(Level level){this(SatelliteCargoContent.POD.get(),level);}public SatellitePod setup(int caller,ItemStack...cargo){callerYPos=caller;slots=cargo;return this;}
 @Override protected void defineSynchedData(SynchedEntityData.Builder builder){super.defineSynchedData(builder);builder.define(STATE,STATE_LEGS_UP);}public boolean doesDeployLegs(){return entityData.get(STATE)==STATE_LEGS_DOWN;}public void setDeployLegs(boolean deploy){entityData.set(STATE,deploy?STATE_LEGS_DOWN:STATE_LEGS_UP);}@Override public boolean isPickable(){return true;}
 @Override public boolean hurt(DamageSource source,float amount){if(isInvulnerableTo(source))return false;if(amount>=5F&&!level().isClientSide&&!isRemoved()){discard();var blast=new com.hbm.explosion.vanillant.ExplosionVNT(level(),getX(),getY()+1.5,getZ(),15F);blast.setEntityProcessor(new com.hbm.explosion.vanillant.standard.EntityProcessorCrossSmooth(1D,50));blast.setPlayerProcessor(new com.hbm.explosion.vanillant.standard.PlayerProcessorStandard());blast.setSFX(new com.hbm.explosion.vanillant.standard.ExplosionEffectWeapon(10,2.5F,1F));blast.explode();if(getDeltaMovement().y!=0)com.hbm.explosion.ExplosionLarge.spawnShrapnelShower(level(),getX(),getY()+1.5,getZ(),getDeltaMovement().x,getDeltaMovement().y,getDeltaMovement().z,15,.25);}return true;}
 @Override public void tick(){if(!level().isClientSide){if(isLanding()){if(timer>0){timer++;setPos(getX(),Math.ceil(getY()),getZ());if(timer>=100)unloadItems();}else if(onGround()){speed=0;timer=1;setDeployLegs(true);}else{if(getY()<callerYPos+17&&!doesDeployLegs())setDeployLegs(true);if(getY()<callerYPos+25)speed-=.01;speed=net.minecraft.util.Mth.clamp(speed,.025D,.75D);}setDeltaMovement(getDeltaMovement().x,-speed,getDeltaMovement().z);}else{setOnGround(false);speed+=.01;if(speed>=.2)setDeployLegs(false);speed=net.minecraft.util.Mth.clamp(speed,0D,2D);setDeltaMovement(getDeltaMovement().x,speed,getDeltaMovement().z);if(getY()>300)discard();}}else{prevLegs=legs;legs+=doesDeployLegs()?LEG_SPEED:-LEG_SPEED;legs=net.minecraft.util.Mth.clamp(legs,0F,1F);if(legs>0&&getDeltaMovement().y<0||getDeltaMovement().y>0)com.hbm.particle.LegacyFluidEffects.gasFlame(level(),getX(),getY()+.5,getZ(),0,speed-1,0);}super.tick();}
 public void unloadItems(){var pos=net.minecraft.core.BlockPos.containing(getX(),getY()-.5,getZ());if(level().getBlockState(pos).is(SatelliteCargoContent.BLOCK.get())&&level().getBlockEntity(pos) instanceof SatelliteDockBlockEntity dock)for(int i=0;i<slots.length;i++){var stack=slots[i];if(stack==null||stack.isEmpty())continue;slots[i]=dock.acceptCargo(stack);}for(var stack:slots)if(stack!=null&&!stack.isEmpty())spawnAtLocation(stack,.25F);slots=new ItemStack[0];}
 public boolean isLanding(){return slots.length>0;}
 @Override protected void onImpact(HitResult hit){if(hit instanceof BlockHitResult){setPos(hit.getLocation());setOnGround(true);if(speed<-.02)hurt(damageSources().generic(),10F);}}
 @Override public boolean doesImpactEntities(){return false;}@Override protected float getAirDrag(){return 1F;}@Override protected float getWaterDrag(){return 1F;}@Override public double getGravityVelocity(){return 0D;}@Override protected MovementEmission getMovementEmission(){return MovementEmission.NONE;}@Override public int legacyTrackingRange(){return 1000;}
 @Override public String getUnlocalizedName(){return "radar.target.dropship";}@Override public int getBlipLevel(){return SPECIAL;}@Override public boolean canBeSeenBy(Object radar){return !(radar instanceof TurretRadarObserver);}@Override public boolean paramsApplicable(RadarScanParams params){return params.scanMissiles;}@Override public boolean suppliesRedstone(RadarScanParams params){return false;}
 @Override protected void addAdditionalSaveData(CompoundTag tag){super.addAdditionalSaveData(tag);tag.putInt("state",entityData.get(STATE));tag.putInt("timer",timer);tag.putInt("callerYPos",callerYPos);tag.putDouble("speed",speed);tag.putInt("itemCount",slots.length);var list=new ListTag();for(int i=0;i<slots.length;i++)if(slots[i]!=null&&!slots[i].isEmpty()){var entry=(CompoundTag)slots[i].save(level().registryAccess());entry.putByte("slot",(byte)i);list.add(entry);}tag.put("items",list);}
 @Override protected void readAdditionalSaveData(CompoundTag tag){super.readAdditionalSaveData(tag);entityData.set(STATE,tag.getInt("state"));timer=tag.getInt("timer");callerYPos=tag.getInt("callerYPos");speed=tag.getDouble("speed");slots=new ItemStack[Math.max(0,tag.getInt("itemCount"))];java.util.Arrays.fill(slots,ItemStack.EMPTY);for(var value:tag.getList("items",Tag.TAG_COMPOUND)){var entry=(CompoundTag)value;int slot=entry.getByte("slot")&255;if(slot<slots.length)slots[slot]=ItemStack.parseOptional(level().registryAccess(),entry);}}
}
